                created.append(job_id)
            except JobCreationException as e:
                click.echo(str(e))
                click.echo(
                    "Error will probably keep occurring. Stopping further job creation."
                )
                break
        return created

    # Patch only for this invocation. Assigning onto the client class leaks the
    # fake into later commands and then no jobs are posted.
    if dry_run:
        with patch.object(
            context.client_tool, "create_path_job", mock_create
        ), patch.object(context.client_tool, "create_pacs_job", mock_create):
            created_job_ids = create_jobs()
    else:
        created_job_ids = create_jobs()

    click.echo(f"created {len(created_job_ids)} jobs: {created_job_ids}")

    if created_job_ids:
        context.add_to_batch(created_job_ids)

    click.echo("Done")


