def _parameters_to_create(job_set) -> List[Parameter]:
    """Row parameters plus defaults that are not already in the row.

    Defaults are stored beside ``parameters``. ``create_job_for_element`` builds
    a new set from the list it is given, so project and destination never reached
    the server when a mapping relied on them.
    """
    params = list(job_set.parameters)
    extra = job_set.__dict__.get("default_parameters") or []
    seen = {type(param) for param in params}
    for param in extra:
        if type(param) not in seen:
            params.append(param)
            seen.add(type(param))
    return params


