def _install_dry_run_fakes(tool, fake):
    """Shadow create_* on this client only. Never touch the class.

    Class-level assignment leaked the fake into every later client in the
    process, so both folder and PACS creates exited 0 without posting.
    """
    records = []
    for name in ("create_path_job", "create_pacs_job"):
        own = getattr(tool, "__dict__", None)
        had_own = isinstance(own, dict) and name in own
        previous_own = own.get(name) if had_own else None
        children = getattr(tool, "_mock_children", None)
        had_child = isinstance(children, dict) and name in children
        previous_child = children.get(name) if had_child else None
        setattr(tool, name, fake)
        records.append((name, had_own, previous_own, had_child, previous_child))
    return records


def _remove_dry_run_fakes(tool, records):
    for name, had_own, previous_own, had_child, previous_child in records:
        children = getattr(tool, "_mock_children", None)
        if isinstance(children, dict):
            if had_child:
                children[name] = previous_child
            else:
                children.pop(name, None)
        own = getattr(tool, "__dict__", None)
        if isinstance(own, dict):
            if had_own:
                own[name] = previous_own
            elif name in own:
                del own[name]


